const channels = [
  {n:'7.1',name:'KXAN',source:'Antenna',type:'OTA',mode:'native',color:'#1d5f9f',programs:[['Today in Austin','9:00–11:00 AM','Local headlines, weather and the stories shaping Central Texas this morning.'],['Studio 512','11:00–11:30 AM','Austin food, people and culture.'],['KXAN News','11:30 AM–12:00 PM','Local news live from Austin.'],['Days of Our Lives','12:00–1:00 PM','Drama series.']]},
  {n:'18.1',name:'KVUE',source:'Antenna',type:'OTA',mode:'native',color:'#b1262f',programs:[['Good Morning Texas','9:00–10:00 AM','Local conversations and lifestyle stories.'],['The View','10:00–11:00 AM','Daytime talk and current events.'],['KVUE Midday','11:00–12:00 PM','Central Texas news and weather.'],['General Hospital','12:00–1:00 PM','Daytime drama.']]},
  {n:'42',name:'Top Gear',source:'Pluto TV',type:'FAST',mode:'handoff',color:'#f05a28',programs:[['Top Gear: Patagonia','9:00–10:00 AM','The team tackles an epic road trip.'],['Top Gear Specials','10:00–11:00 AM','Classic challenges and adventures.'],['Top Gear','11:00 AM–12:00 PM','Motoring, mayhem and machines.'],['Fifth Gear','12:00–1:00 PM','Performance car tests.']]},
  {n:'101',name:'CBS News',source:'Pluto TV',type:'FAST',mode:'handoff',color:'#315cad',programs:[['CBS News 24/7','9:00–10:00 AM','Continuous national and world news.'],['America Decides','10:00–11:00 AM','Political news and analysis.'],['CBS News 24/7','11:00 AM–12:00 PM','Breaking news coverage.'],['MoneyWatch','12:00–1:00 PM','Business and markets.']]},
  {n:'206',name:'ESPN',source:'YouTube TV',type:'SUBSCRIPTION',mode:'handoff',color:'#b31c27',programs:[['SportsCenter','9:00–10:00 AM','Scores, highlights and breaking sports news.'],['First Take','10:00 AM–12:00 PM','Sports debate and analysis.'],['NFL Live','12:00–1:00 PM','The latest from around the NFL.'],['College Football','1:00–4:00 PM','Live college football.']]},
  {n:'301',name:'Apple TV+',source:'Apple TV',type:'SUBSCRIPTION',mode:'handoff',color:'#353d48',programs:[['Slow Horses','Continue · S4 E3','A dysfunctional team of MI5 agents navigates the espionage world.'],['The Morning Show','Up next · S3 E1','The future of a network morning show hangs in the balance.'],['Ted Lasso','S3 E8','An American coach brings optimism to English football.'],['Severance','S2 E1','Work and personal memories remain divided.']]},
  {n:'408',name:'MovieSphere',source:'Free stream',type:'FAST',mode:'native',color:'#6d3ba8',programs:[['The Great Escape','9:00–11:50 AM','Allied prisoners plan a daring escape.'],['Cinema Stories','11:50 AM–12:20 PM','Behind the scenes of classic films.'],['North by Northwest','12:20–2:40 PM','A case of mistaken identity.'],['The Third Man','2:40–4:30 PM','Mystery in postwar Vienna.']]},
  {n:'501',name:'Ireland FM',source:'Patrick TV',type:'FAST',mode:'native',color:'#16885f',programs:[['The Morning Session','9:00–11:00 AM','Irish favorites, stories and personal callouts.'],['Patrick\'s Mix','11:00 AM–1:00 PM','Your music with an AI host between songs.'],['Dublin to Austin','1:00–3:00 PM','Music connecting home and home.'],['The Session','3:00–5:00 PM','Traditional and modern Irish sounds.']]}
];

let row=0,col=0,filter='ALL',view='live';
const isFireTV=/Silk|AFT|FireTV/i.test(navigator.userAgent);
const favorites=new Set(JSON.parse(localStorage.getItem('patrick-tv-favorites')||'[]'));
const $=s=>document.querySelector(s);
const grid=$('#guideGrid'),scroll=$('#guideScroll');

function visible(){return channels.filter(c=>filter==='ALL'||c.type===filter).filter(c=>filter!=='FAVORITES'||favorites.has(c.n));}
function render(){
  const list=visible(); if(row>=list.length)row=Math.max(0,list.length-1);
  grid.innerHTML=['<div class="time-head">CHANNEL</div>','<div class="time-head">NOW</div>','<div class="time-head">10:30</div>','<div class="time-head">11:30</div>','<div class="time-head">12:30</div>'].join('');
  list.forEach((c,ri)=>{
    grid.insertAdjacentHTML('beforeend',`<div class="channel-cell"><span class="channel-number">${c.n}</span><span class="channel-icon" style="--icon:${c.color}">${c.name.slice(0,4)}</span><span><div class="channel-name">${c.name}</div><div class="channel-source">${c.source}</div></span>${favorites.has(c.n)?'<span class="star">★</span>':''}</div>`);
    c.programs.forEach((p,ci)=>grid.insertAdjacentHTML('beforeend',`<div class="program-cell ${c.mode} ${ri===row&&ci===col?'selected':''}" data-row="${ri}" data-col="${ci}" tabindex="-1"><div class="program-name">${p[0]}</div><div class="program-time">${p[1]}</div></div>`));
  });
  grid.querySelectorAll('.program-cell').forEach(el=>el.addEventListener('click',()=>{row=+el.dataset.row;col=+el.dataset.col;selectCurrent(true)}));
  updateInfo();
}
function current(){const list=visible();return {c:list[row]||channels[0],p:(list[row]||channels[0]).programs[col]};}
function updateInfo(){
  const {c,p}=current();
  $('#stationBug').innerHTML=`${c.n}<br><span>${c.name}</span>`;$('#channelLabel').textContent=`${c.n} ${c.name}`;$('#sourceLabel').textContent=c.source;$('#programTitle').textContent=p[0];$('#programMeta').textContent=`${p[1]} · ${c.type==='OTA'?'Live TV':c.source}`;$('#programDescription').textContent=p[2];$('#nativeBadge').textContent=c.mode==='native'?`LIVE · ${c.type}`:`VIA · ${c.source.toUpperCase()}`;$('#favoriteBtn').classList.toggle('is-favorite',favorites.has(c.n));$('#favoriteBtn').textContent=favorites.has(c.n)?'★':'☆';$('#watchBtn').textContent=c.mode==='native'?'WATCH LIVE':`OPEN ${c.source.toUpperCase()}`;
  document.documentElement.style.setProperty('--channel-accent',c.color);
}
function selectCurrent(tune=false){render();const selected=$('.program-cell.selected');selected?.scrollIntoView({block:'nearest',inline:'nearest'});if(tune)watch();}
function watch(){const {c,p}=current();if(c.mode==='native'){showToast(`Tuned to ${c.name} · ${p[0]}`);$('#videoStage').animate([{filter:'brightness(.6)'},{filter:'brightness(1)'}],{duration:500});return}openHandoff(c,p)}
function openHandoff(c,p){$('#providerLogo').textContent=c.source==='Apple TV'?'tv+':c.source==='YouTube TV'?'YouTube TV':'PLUTO TV';$('#modalEyebrow').textContent=c.source.toUpperCase();$('#modalTitle').textContent=`Open ${p[0]}?`;$('#modalCopy').textContent=`Playback is controlled by ${c.source}. Patrick TV will take you there and remember your place in the guide.`;$('#launchBtn').textContent=`OPEN ${c.source.toUpperCase()}`;$('#modal').hidden=false;$('#modalClose').focus()}
function closeModal(){$('#modal').hidden=true;scroll.focus()}
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>t.classList.remove('show'),2300)}
function toggleFavorite(){const {c}=current();favorites.has(c.n)?favorites.delete(c.n):favorites.add(c.n);localStorage.setItem('patrick-tv-favorites',JSON.stringify([...favorites]));render();showToast(favorites.has(c.n)?`${c.name} added to My Channels`:`${c.name} removed from My Channels`)}
function setView(v){view=v;document.body.classList.toggle('full-view',v==='full');document.querySelectorAll('.view-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='full')showToast('Full Guide view');}
function moveSelection(key){const list=visible();if(key==='ArrowDown')row=Math.min(list.length-1,row+1);if(key==='ArrowUp')row=Math.max(0,row-1);if(key==='ArrowRight')col=Math.min(3,col+1);if(key==='ArrowLeft')col=Math.max(0,col-1);selectCurrent()}

scroll.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Enter',' ','f','F','g','G'].includes(e.key))e.preventDefault();if(e.key.startsWith('Arrow'))return moveSelection(e.key);if(e.key==='Enter'||e.key===' ')return watch();if(e.key.toLowerCase()==='f')return toggleFavorite();if(e.key.toLowerCase()==='g')return setView(view==='live'?'full':'live')});
document.querySelectorAll('.view-btn').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;row=0;col=0;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));render()}));
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x===b));if(b.dataset.section==='GUIDE')setView('full');else if(b.dataset.section==='LIVE')setView('live');else if(b.dataset.section==='FAVORITES'){filter='FAVORITES';row=0;render();showToast(favorites.size?'Showing My Channels':'No favorites yet — press F on a channel')}else{filter='ALL';render();showToast(`${b.dataset.section} collection preview`)}}));
$('#watchBtn').addEventListener('click',watch);$('#favoriteBtn').addEventListener('click',toggleFavorite);$('#modalClose').addEventListener('click',closeModal);$('#cancelBtn').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});$('#launchBtn').addEventListener('click',()=>{const {c}=current();closeModal();showToast(`${c.source} handoff simulated in this prototype`)});document.addEventListener('keydown',e=>{if((e.key==='Escape'||e.key==='BrowserBack')&&!$('#modal').hidden){e.preventDefault();closeModal();return}if(isFireTV&&document.activeElement!==scroll&&e.key.startsWith('Arrow')){e.preventDefault();scroll.focus();moveSelection(e.key)}if(isFireTV&&e.key==='MediaPlayPause'){e.preventDefault();watch()}});
function registerAgentTools(){
  const context=document.modelContext;if(!context?.registerTool)return;
  const register=tool=>{try{Promise.resolve(context.registerTool(tool)).catch(()=>{})}catch{}}
  register({name:'tune_channel',title:'Tune channel',description:'Select a Patrick TV channel by its displayed channel number and begin its normal watch or provider-handoff flow.',inputSchema:{type:'object',properties:{channel_number:{type:'string'}},required:['channel_number'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.channel_number!=='string')throw new Error('channel_number must be a string');filter='ALL';const index=channels.findIndex(c=>c.n===input.channel_number);if(index<0)throw new Error('Channel not found');row=index;col=0;render();watch();return{channel:channels[index].name,number:channels[index].n,playback:channels[index].mode==='native'?'in_app':'provider_handoff'}}});
  register({name:'set_guide_view',title:'Change guide view',description:'Switch between the live-picture guide and the full-screen channel guide.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['live','full']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['live','full'].includes(input.view))throw new Error('view must be live or full');setView(input.view);return{view:input.view}}});
  register({name:'set_channel_favorite',title:'Set channel favorite',description:'Add or remove a Patrick TV channel from My Channels.',inputSchema:{type:'object',properties:{channel_number:{type:'string'},favorite:{type:'boolean'}},required:['channel_number','favorite'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const c=channels.find(x=>x.n===input?.channel_number);if(!c||typeof input.favorite!=='boolean')throw new Error('Provide a valid channel_number and favorite boolean');input.favorite?favorites.add(c.n):favorites.delete(c.n);localStorage.setItem('patrick-tv-favorites',JSON.stringify([...favorites]));render();return{channel:c.name,favorite:favorites.has(c.n)}}});
}
function tick(){const d=new Date();$('#clock').textContent=d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}tick();setInterval(tick,30000);render();registerAgentTools();if(isFireTV){document.body.classList.add('fire-tv');$('#deviceBadge').hidden=false;$('#guideHelp').textContent='REMOTE: arrows move  •  SELECT tunes  •  BACK closes';setTimeout(()=>scroll.focus(),350)}
